-- Creators: a reference list of the top 100 YouTube video podcasts (US 40, India 35, rest of world 25).
-- Plain columns identify the show and its YouTube channel(s); everything descriptive lives in `profile` (JSON), so new
-- attributes can be added without a schema change and the whole profile can be handed to the AI as is.
--
-- profile keys: hosts, host_background (short; missing when none was given), host_bio, topics, known_for, criticism,
-- biases, controversies. These are AI-compiled research notes about real people, not checked facts: use them as
-- context for analysis only, never as statements shown to users.
--
-- Matching a video to its creator: the episode's channel has a YouTube channel ID (channels.youtube_channel_id), e.g.
--   select cr.* from public.creators cr join public.channels ch on ch.youtube_channel_id = any(cr.youtube_channel_ids)
--   where ch.id = :channel_id;
-- Some shows publish on two channels (e.g. La Cotorrisa alternates between both hosts' channels), so both IDs are
-- listed. Shameless (#100) has no channel found yet, so its arrays are empty.
--
-- Not readable with the anon key (RLS on, no public policy).
create table public.creators (
  id uuid primary key default gen_random_uuid(),
  rank smallint not null unique check (rank between 1 and 100),
  podcast text not null,
  youtube_channel_name text not null,                -- official channel name, e.g. 'PowerfulJRE'
  youtube_handles text[] not null default '{}',      -- e.g. {'@joerogan'}
  youtube_channel_ids text[] not null default '{}',  -- 'UC...' IDs, same order as youtube_handles
  market text not null check (market in ('us', 'india', 'global')),
  country text not null,                             -- 'US', 'India', 'UK', 'UK / US', 'Japan (Intl)', ...
  profile jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (cardinality(youtube_handles) = cardinality(youtube_channel_ids))
);
create index creators_market_rank_idx on public.creators (market, rank);
create index creators_youtube_channel_ids_idx on public.creators using gin (youtube_channel_ids);

create trigger creators_set_updated_at before update on public.creators
  for each row execute function public.set_updated_at();

alter table public.creators enable row level security;
grant all on public.creators to service_role;

